function updateLicenseTypeLabel() {
	var label = gs.getMessage('Perpetual');

	var grLt = new GlideRecord('sys_choice');
	grLt.addQuery('name', 'alm_license');
	grLt.addQuery('value', 'full');
	grLt.addQuery('element', 'product_type');
	grLt.addQuery('language', 'en');
	grLt.query();

	if (grLt.next()) {
		grLt.setValue('label', label);
		grLt.update();
	}
}

updateLicenseTypeLabel();
